const { formatUptime, formatUptimeVerbose, extractNumber, progressBar } = require('../lib/helpers');

function buildCommand() {
  const __args = [['country'], 'Utility', 'Get info about a country', async ({ sock, from, msg, args }) => {
  const name = args.join(' ');
  if (!name) return sock.sendMessage(from, { text: 'Usage: .country Nigeria' }, { quoted: msg });
  try {
    const res = await fetch(`https://restcountries.com/v3.1/name/${encodeURIComponent(name)}`);
    const [d] = await res.json();
    await sock.sendMessage(from, { text: `🏳️ *${d.name.common}*\nCapital: ${d.capital?.[0]}\nRegion: ${d.region}\nPopulation: ${d.population.toLocaleString()}` }, { quoted: msg });
  } catch (e) {
    await sock.sendMessage(from, { text: 'Country not found.' }, { quoted: msg });
  }
}];
  const [commandsArr, section, description, handler, opts = {}] = __args;
  return { commands: commandsArr, section, description, handler, ownerOnly: !!opts.ownerOnly };
}

module.exports = buildCommand();
